def compute(vars):
    value_amount = vars["v1"]
    useful_life_years = vars["v2"]
    if useful_life_years == 0:
        return None
    annual_amortization = value_amount / useful_life_years
    return {
        "value": annual_amortization,
        "trace": {
            "value_amount": value_amount,
            "useful_life_years": useful_life_years,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "USD per year"
            }
        }
    }
